last_SFS = payslip._l10n_do_get_previous_same_month_line_total('SFST', absolute=True) if has_prior_same_month_payslip else 0.0

if payslip._get_l10n_do_effective_schedule_pay() == 'hourly':
    result = -(min(GROSS, cap_base) * sfs)
else:
    if payslip_day >= 25 and payslip_day <= 31 and not weekly_mode and has_prior_same_month_payslip:
        closing_base = min(accumulated_period_base, cap_base)
        # Tope ARS mensual
        if accumulated_period_base > cap_base:
            result = -(cap_amount - last_SFS)
        else:
            result = -((closing_base * sfs) - last_SFS)
    elif payslip.pay_vacation and payslip.vacation_type == 'enjoyed':
        result = -(min(GROSS, cap_base) * sfs)
    else:
        # Primera quincena
        if (GROSS) > cap_base:
            result = -(cap_amount * half_factor)
        else:
            if payslip._l10n_do_has_manual_partial_worked_days():
                result = -(GROSS * sfs)
            else:
                result = -((GROSS * sfs) * half_factor)

