date_to = payslip.date_to
payslip_day = date_to.day
weekly_mode = payslip.employee_id.deduction_calc_mode == 'period' and payslip.employee_id.deduction_calc_period == 'weekly'
half_factor = 1.0 if weekly_mode else 0.5
has_prior_same_month_payslip = payslip._l10n_do_has_previous_same_month_payslip()
accumulated_period_base = payslip._l10n_do_get_accumulated_contribution_period_base()
# Tasa SRL configurable por empresa o parámetro; por defecto 1.04%
rate = None
cap_base = payslip._l10n_do_get_salary_cap('srl')
# Leer de la compañía (campo computado l10n_do_srl_rate)
try:
    comp = payslip.company_id
    val = comp.l10n_do_srl_rate if comp else None
    if val in (False, None, ''):
        # Fallback: construir desde categoría y sus tasas
        cat = comp.l10n_do_srl_category if comp else None
        rate_map = {
            '1': comp.l10n_do_srl_rate_cat1 if comp else None,
            '2': comp.l10n_do_srl_rate_cat2 if comp else None,
            '3': comp.l10n_do_srl_rate_cat3 if comp else None,
            '4': comp.l10n_do_srl_rate_cat4 if comp else None,
        }
        val = rate_map.get(cat or '1')
    rate = float(val) if val not in (False, None, '') else None
except:
    rate = None

# Fallback: parámetro del sistema
if rate is None:
    try:
        param = payslip.env['ir.config_parameter'].sudo().get_param('l10n_do_payroll.srl_rate')
        rate = float(param) if param else None
    except:
        rate = None

# Default si no hay configuración válida
if not rate or rate <= 0:
    rate = 0.0104

# Normalizar: si viene como porcentaje (ej. 1.10), convertir a tasa (0.0110)
if rate >= 1:
    rate = rate / 100.0

if payslip._get_l10n_do_effective_schedule_pay() == 'hourly':
    result = min(GROSS, cap_base) * rate
else:
    if payslip_day >= 25 and payslip_day <= 31 and not weekly_mode and has_prior_same_month_payslip:
        last_SRL_E = payslip._l10n_do_get_previous_same_month_line_total('SRL E')
        result = (min(accumulated_period_base, cap_base) * rate) - last_SRL_E
    else:
        if payslip._l10n_do_has_manual_partial_worked_days():
            result = min(GROSS, cap_base) * rate
        else:
            result = min(GROSS, cap_base) * rate * half_factor

